from pathlib import Path
import json,re,hashlib,itertools
root=Path('docs/learning-pack-source/실험04/problem-explanations')
data={
'q-mux2':(['“2×1 MUX”와 NOT 1개·AND 2개·OR 1개라는 조건에서 데이터 선택을 떠올려요. MUX는 여러 데이터 중 하나를 한 출력에 전달해요.','Y=S′I0+SI1에서 S는 선택선, I0·I1은 데이터예요. ′는 NOT, 붙여 쓰기는 AND, +는 OR예요.','이상 조합회로에서 S=0이면 첫 항만, S=1이면 둘째 항만 열려요. 이 선택 조건이 두 AND 경로와 마지막 OR를 정하는 이유예요.'], 'Y=S′I0+SI1: S=0은 I0, S=1은 I1을 선택해요.'),
'q-mux4':(['“Enable을 갖는 4×1”에서는 주소와 활성 조건을 따로 읽어요. S1이 상위, S0가 하위 비트라 k=2S1+S0가 선택 데이터 Dk의 번호예요.','원문 회로는 E를 반전하므로 E=0에서 활성이고 Y=E′(S1′S0′D0+S1′S0D1+S1S0′D2+S1S0D3)예요. ′는 NOT, +는 OR예요.','이 NAND 두 단계 회로의 이상 논리 계산에서는 E=1이면 모든 첫 NAND 출력이 1이라 마지막 출력은 0이에요. 교안의 비활성 X 표기를 측정값으로 확정하지 않아요. 제시 네 행은 E=0이므로 D3·D2·D1·D0 열에서 선택 이름만 찾아요.'], 'E=0에서 활성이고 k=2S1+S0로 Dk를 골라요. 비활성 출력 0은 제시 회로의 이상 계산 조건이에요.'),
'q-demux2':(['“1×2 DMUX”는 한 데이터 D를 두 출력 중 한 곳에 분배하라는 단서예요. S는 보내는 출력 번호를 골라요.','활성 High AND형 이상 회로에서 Y0=DS′, Y1=DS예요. ′는 NOT이고 곱은 AND예요.','S=0이면 Y0만 D를 따라가고, S=1이면 Y1만 D를 따라가며 선택되지 않은 출력은 0이에요. 두 출력에 각각 AND를 두는 이유이며 D=0이면 선택 출력도 0이에요.'], 'AND형 DMUX는 Y0=DS′, Y1=DS로 선택 출력에 D를 전달해요.'),
'q-design4':(['“NOT 2개·3입력 AND 4개·4입력 OR 1개”라는 제약에서 네 주소 minterm을 떠올려요. minterm은 특정 비트 조합에서만 1인 AND 조건이에요.','S1S0=00·01·10·11의 조건은 S1′S0′·S1′S0·S1S0′·S1S0예요. S1은 상위 비트이고 ′는 NOT이에요. 각 조건에 I0·I1·I2·I3를 각각 AND하고 네 항을 OR해요.','선택 비트가 안정된 이상 회로에서는 네 조건 중 하나만 1이므로 선택 입력만 남아요. 원문에 enable이 없어서 E를 추가하지 않고, 반전선 두 개를 공유해야 지정 게이트 수를 지켜요.'], '네 주소 minterm에 각각 Ik를 AND하고 OR해요. NOT2·3입력 AND4·4입력 OR1, enable 없음이 조건이에요.'),
'q-decoder':(['“디코더와 연관 지어”라는 말에서 이진 주소를 one-hot 선택선으로 해독하는 개념을 떠올려요. one-hot은 여러 선 중 하나만 활성인 상태예요.','활성 High 디코더에서 Ck는 주소 k일 때만 1이에요. n비트 주소는 최대 2ⁿ개 선택을 구분해요. MUX는 Y=ΣCkIk로 모으고 DMUX는 Yk=DCk로 나눠요. Σ는 OR, 곱은 AND예요.','enable이 허용되고 한 주소가 정해진 이상 모델 조건이에요. D=1인 DMUX는 디코더와 같은 선택 출력을 내므로 관계를 설명할 수 있어요. 활성 Low 소자에는 이 식을 극성 확인 없이 그대로 쓰지 않아요.'], '디코더는 주소→one-hot, MUX는 Y=ΣCkIk, DMUX는 Yk=DCk로 데이터를 제어해요.'),
'q-tri':(['“Tri-state buffer”와 공통 출력선에서는 0·1 외의 High-Z를 떠올려요. Z는 논리 0이 아니라 출력을 구동하지 않는 높은 임피던스 상태예요.','원문 기능표는 nOE=0일 때 B=A, nOE=1일 때 B=Z예요. nOE는 활성 Low 제어라 I0 버퍼에 nOE0=S, I1 버퍼에 nOE1=S′를 연결해요. ′는 NOT이에요.','안정된 S에서 하나만 구동하고 다른 하나가 Z여야 공통선이 선택 데이터를 전달해요. 둘 다 구동하면 다른 값에서 버스 충돌이 생겨요. 실제 전환 지연은 별도이며 제공 답안의 active-high 조건 충돌은 유지해요.'], 'Z는 0이 아니라 구동 중단이에요. 원문 Low 활성 표에 따라 nOE0=S, nOE1=S′로 하나만 켜요. 답안 충돌은 유지해요.'),
'q-muxdef':(['“멀티플렉서에 대해 서술”에서는 여러 입력 중 하나를 선택하는 정의를 떠올려요. 데이터 입력은 전달할 값이고 선택선은 경로 번호예요.','2ⁿ→1 MUX는 데이터 입력 2ⁿ개, 선택선 n개, 데이터 출력 1개예요. 4×1이면 S1S0가 주소이고 Y=Ik, k=2S1+S0예요.','기능이 허용된 이상 선택 조건에서 선택 데이터의 0과 1을 모두 전달해요. 정의에 선택선과 데이터 경로를 함께 써야 입력을 모두 더한다는 오해를 피할 수 있어요.'], 'MUX는 선택선이 지정한 여러 데이터 중 하나를 한 출력에 전달해요. 2ⁿ개 데이터에 선택선 n개가 필요해요.'),
'q-demuxdef':(['“디멀티플렉서에 대해 서술”에서는 한 입력을 선택한 출력으로 보내는 분배 정의를 떠올려요. D는 데이터, 선택선은 목적지 번호예요.','1→2ⁿ DMUX는 데이터 입력 1개, 선택선 n개, 출력 2ⁿ개예요. 활성 High AND형 모델은 Yk=DCk이고 Ck는 선택 주소에서만 1이에요.','이 모델에서 선택 출력은 D를 따르고 나머지는 0이에요. 실제 소자 극성은 기능표로 확인해야 해요. 답안 자료의 정의를 설명하되 기출 문제지 미확인 표시는 유지해요.'], 'DMUX는 한 데이터를 선택 출력으로 분배해요. AND형은 Yk=DCk이며 기출 문제지 미확인 표시는 유지해요.'),
'q-difference':(['“차이를 서술”하면 데이터 방향과 선택선 역할을 함께 비교해요. MUX는 N→1로 모으고 DMUX는 1→N으로 나눠요.','N=2ⁿ이면 둘 다 n비트 선택선이 경로 번호를 골라요. MUX는 Ik→Y, DMUX는 D→Yk라 선택 대상이 각각 입력과 출력이에요.','여기서 선 수는 데이터 경로를 뜻하고 전체 핀 수가 아니에요. 선택되지 않은 MUX 입력 정보는 잃으므로 DMUX를 정보 복원 역함수라고 할 수 없어요. 답안 자료를 근거로 비교하되 기출 문제지 미확인 표시는 유지해요.'], 'MUX는 N→1의 입력 선택, DMUX는 1→N의 출력 선택이에요. 기출 문제지 미확인 표시는 유지해요.'),
'q-demux4':(['“1×4”와 +5/0 표기에서는 한 데이터를 네 경로로 분배하는 DMUX를 떠올려요. +5는 High(1), 0은 Low(0)로 읽고 S1은 상위·S0는 하위 비트예요.','활성 High AND형 이상 모델은 Y0=DS1′S0′, Y1=DS1′S0, Y2=DS1S0′, Y3=DS1S0예요. ′는 NOT이에요. 주소 k=2S1+S0의 출력만 D를 따라가요.','이 식에서는 D=0이면 모두 0이지만 원문 표에는 X가 있어요. 회로도 없는 해당 답안 페이지의 X를 Z나 실제 비활성 출력으로 확정하지 않아요. Y3부터 Y0인 열 순서를 지키며 답안 충돌·기출 문제지 미확인 표시를 유지해요.'], 'AND형 이상 모델에서 Yk=D·주소조건, D=0이면 모두 0이에요. 원문 X와 계산값은 구별하고 답안 충돌·기출 미확인을 유지해요.'),
'q-mux2-graded':(['“2×1 설계”와 지정 네 행은 일반 선택 식을 해당 행에 적용하라는 단서예요. Sel은 선택선이고 X0·X1은 데이터예요.','Y=Sel′X0+SelX1에서 ′는 NOT, 곱은 AND, +는 OR예요. Sel=0은 X0, Sel=1은 X1만 남겨 선택 데이터를 전달해요.','이상 조합회로 기준으로 NOT1·AND2·OR1을 사용해요. 원문 Sel,X0,X1의 000·101·010·111 순서를 보존해야 하므로 일반 여덟 행으로 바꾸지 않아요.'], 'Y=Sel′X0+SelX1을 지정 네 행 000·101·010·111에 적용해요. 행 순서는 그대로예요.'),
'q-active-general':(['“active high와 active low”에서는 기능이 유효해지는 제어 수준을 떠올려요. High 활성은 1에서, Low 활성은 0에서 해당 기능이 실행돼요.','enable은 데이터 전달 허용 여부이고 데이터 출력값과 달라요. nOE·윗줄·입력 버블은 Low 활성의 단서이며 최종 판단은 기능표로 확인해요.','어떤 기능을 제어하는 신호인지 지정해야 정의가 성립해요. nOE=0인 버퍼에 A=1을 넣으면 B=1이라 활성 조건 0이 출력 0을 뜻하지 않아요. 이 구별이 두 정의를 정확히 서술하는 이유예요.'], 'High 활성은 1, Low 활성은 0에서 기능이 유효해요. 활성 수준과 데이터 출력값을 구별해요.')}
original={}
for ident,(paras,summary) in data.items():
 p=root/(ident+'.html');old=p.read_text(encoding='utf-8');original[ident]=old
 recall='<div class="layer formal" data-explanation="recall"><span class="layer-title">이 문제를 봤을 때 떠올릴 개념과 공식</span>'+''.join('<p>'+s+'</p>' for s in paras)+'</div>'
 new=old.replace('<div class="layer formal" data-explanation="start">',recall+'<div class="layer formal" data-explanation="start">',1).replace('<div class="sum" hidden>','<div class="sum" hidden><p data-summary="recall">'+summary+'</p>',1)
 assert new.replace(recall,'',1).replace('<p data-summary="recall">'+summary+'</p>','',1)==old
 p.write_text(new,encoding='utf-8')
Path('output/validation/problem-recall/original-fragments-04.json').write_text(json.dumps(original,ensure_ascii=False,indent=2),encoding='utf-8')
p=root.parent/'manifest.json';old=p.read_text(encoding='utf-8');assert '"problem_explanation_version": 1' in old;p.write_text(old.replace('"problem_explanation_version": 1','"problem_explanation_version": 2'),encoding='utf-8')
print('12 recalls and summaries; old six sections and summaries exact preserved')
